const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
function md(value,{paragraphs=false}={}){
  let tokens=[],blocks=new Set();
  const stash=(html,block=false)=>{tokens.push(html);if(block)blocks.add(tokens.length-1);return `\uE000${tokens.length-1}\uE001`;};
  let text=String(value??'').replace(/!\[([^\]]*)\]\(([^)]+)\)/g,(_,alt,url)=>{
    const hash=url.match(/(?:sha256\/|question-assets\/)([a-f0-9]{64})/i)?.[1];
    const path=hash&&assets[hash]?.path;
    if(path&&/^question-assets\/[a-f0-9]{64}\.(png|jpg|jpeg|webp|gif|avif)$/.test(path))return stash(`<img src="/${path}" alt="${escape(alt||'题目配图')}" loading="lazy">`);
    if(/^\/assets\/[a-zA-Z0-9_.-]+$/.test(url))return stash(`<img src="${escape(url)}" alt="${escape(alt)}" loading="lazy">`);
    return stash(`<span class="missing-asset" title="${escape(hash||url)}">${icon('info')} ${escape(alt||'题目配图')}：离线图片暂缺${hash?` · ${hash.slice(0,8)}`:''}</span>`);
  });
  text=text.replace(/\[([^\]\n]+)\]\(([^)\n]+)\)/g,(raw,label,url)=>{
    if(!/^https?:\/\/[^\s<>]+$/i.test(url))return raw;
    try{
      const href=new URL(url);
      if(!['http:','https:'].includes(href.protocol)||!href.hostname)return raw;
      return stash(`<a href="${escape(href.href)}" target="_blank" rel="noopener noreferrer">${escape(label)}</a>`);
    }catch{return raw;}
  });
  text=text.replace(/\$\$([\s\S]*?)\$\$|\$([^$\n]+)\$|\\\[([\s\S]*?)\\\]|\\\(([\s\S]*?)\\\)/g,(raw,a,b,c,d)=>{
    const latex=a??b??c??d;
    try{return stash(window.katex?window.katex.renderToString(latex,{displayMode:a!==undefined||c!==undefined,throwOnError:false,trust:false,strict:'ignore',maxExpand:1000}):`<code class="math-fallback">${escape(raw)}</code>`,a!==undefined||c!==undefined);}catch{return stash(`<code class="math-fallback">${escape(raw)}</code>`);}
  });
  text=escape(text).replace(/^###?\s+(.+)$/gm,'<h3>$1</h3>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');
  const lines=text.split('\n'),blockLine=line=>{const match=line.trim().match(/^\uE000(\d+)\uE001$/);return match&&blocks.has(Number(match[1]));};
  if(paragraphs){
    const sections=[];let paragraph=[],list=[];
    const flush=()=>{if(paragraph.length)sections.push(`<p>${paragraph.join('<br>')}</p>`);paragraph=[];};
    const flushList=()=>{if(list.length)sections.push(`<ul>${list.map(item=>`<li>${item}</li>`).join('')}</ul>`);list=[];};
    for(const line of lines){
      if(!line.trim()){flush();continue;}
      const item=line.match(/^[ \t]*[-*+][ \t]+(.+)$/);
      if(item){flush();list.push(item[1]);continue;}
      flushList();
      if(/^<h3>.*<\/h3>$/.test(line)||blockLine(line)){flush();sections.push(line);}
      else paragraph.push(line);
    }
    flush();flushList();text=sections.join('\n');
  }else text=lines.map((line,i)=>line+(i<lines.length-1&&!blockLine(line)&&!blockLine(lines[i+1])?'<br>':'')).join('');
  return text.replace(/\uE000(\d+)\uE001/g,(_,i)=>tokens[Number(i)]||'');
}
