async function api(path,method='GET',body){const r=await fetch('/api/local'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok||data.code!==0)throw Error(data.message||`请求失败 (${r.status})`);return data.data;}
