function heatmap(){const year=Number(new Intl.DateTimeFormat('en',{timeZone:'Asia/Shanghai',year:'numeric'}).format(new Date())),data=boot.stats.activity_year||[],byDate=new Map(data.map(v=>[v.date,v.attempts])),first=new Date(Date.UTC(year,0,1)),offset=first.getUTCDay(),last=new Date(Date.UTC(year,11,31)),weeks=Math.ceil((offset+Math.round((last-first)/86400000)+1)/7),today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'});let cells='',months=Array(weeks).fill('');for(let i=0;i<weeks*7;i++){let d=new Date(first.getTime()+(i-offset)*86400000),key=d.toISOString().slice(0,10),count=byDate.get(key)||0;if(d.getUTCFullYear()!==year){cells+='<span style="visibility:hidden"></span>';continue;}if(d.getUTCDate()===1)months[Math.floor(i/7)]=`${d.getUTCMonth()+1}月`;cells+=`<button data-action="activity-date" data-date="${key}" data-heatmap-level="${count===0?0:count<5?1:count<15?2:count<30?3:4}" title="${key}：${count} 次作答" aria-label="${key}，${count} 次作答" ${key>today?'disabled data-future="true"':''}></button>`;}return `<section class="${c('browse','activitySurface')} original-surface" aria-label="学习活动"><section class="${c('browse','activityHeatmap')}" style="--heatmap-week-count:${weeks}" aria-label="刷题强度热力图（按作答判定次数）"><header class="${c('browse','activityHeatmapHeader')}"><h3>每日作答</h3><span>${year} 年 · ${data.filter(v=>v.attempts>0).length} 个作答日</span></header><div class="${c('browse','activityHeatmapViewport')}"><div class="${c('browse','activityHeatmapChart')}"><div class="${c('browse','activityHeatmapMonths')}">${months.map(m=>`<span>${m}</span>`).join('')}</div><div class="${c('browse','activityHeatmapWeekdays')}">${['日','一','二','三','四','五','六'].map(d=>`<span>${d}</span>`).join('')}</div><div class="${c('browse','activityHeatmapGrid')}">${cells}</div></div></div><div class="${c('browse','activityHeatmapLegend')}"><strong>刷题强度</strong>${['无','轻','中','高','很高'].map((t,i)=>`<span class="${c('browse','activityHeatmapLegendItem')}"><i data-heatmap-level="${i}"></i>${t}</span>`).join('')}</div></section></section>`;}
async function renderHome(epoch){boot=await api('/bootstrap');if(epoch!==renderEpoch)return;const recent=await api('/records?record_type=all&per_page=5');if(epoch!==renderEpoch)return;const lastId=recent.items[0]?.question_id||boot.stats.last_question_id;let last=lastId?await api(`/questions/${lastId}`):null;if(last&&!last.list_ids.includes(activeBank))last=null;if(epoch!==renderEpoch)return;let cat=last?.category_id||331;const subject=boot.settings.exam_subject||'all';let chapterData=await api('/questions?'+new URLSearchParams({list:activeBank,category:cat,subject,per_page:1}));if(!chapterData.total){const first=await api('/questions?'+new URLSearchParams({list:activeBank,subject,per_page:1}));cat=first.items[0]?.category_id||'';chapterData=await api('/questions?'+new URLSearchParams({list:activeBank,category:cat,subject,per_page:1}));}const chapter=last?.category_full_path||chapterData.items[0]?.category_full_path||'全部分类';if(epoch!==renderEpoch)return;const count=chapterData.total,mastered=Number(findCategory(cat,activeBank)?.mastered_count||0),s=boot.stats,today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'}),days=Math.max(0,Math.ceil((new Date(`${boot.settings.exam_date}T00:00:00+08:00`)-new Date(`${today}T00:00:00+08:00`))/86400000));
 const metric=(name,value,unit,ico,description='')=>`<section class="${c('browse','metricItem')}"><h2 class="${c('browse','metricHeading')}">${icon(ico)} ${name}</h2><div class="${c('browse','metricBody')}"><div class="${c('browse','metricContent')}"><strong class="${c('browse','metricValue')}">${value}<small>${unit}</small></strong>${description?`<p class="${c('browse','metricDescription')}">${description}</p>`:''}</div></div></section>`;
 $('#app').innerHTML=homeShell(`<div class="${c('browse','page')} ${c('browse','dashboardPage')}"><section class="${c('browse','hero')} original-surface"><div class="${c('browse','heroCopy')}"><div class="${c('browse','heroTask')}"><h1>${last?'继续学习':'从一道题开始'}</h1>${!last?'<p class="original-start-intro">先试着作答，再查看答案与解析。</p>':''}<ul class="${c('browse','heroMeta')}"><li class="${c('browse','heroChapter')}"><strong>${escape(last?chapter:nodeLabel(findCategory(cat,activeBank)||{})||chapter)}</strong></li>${last?`<li class="${c('browse','heroDate')}">上次学习 ${escape(localDate(recent.items[0]?.created_at||s.last_activity_at))}</li>`:''}</ul>${last?`<div class="${c('browse','heroProgress')}"><div class="${c('browse','heroProgressMeta')}"><span class="${c('browse','heroProgressMetric')}">已完成 <strong>${mastered}</strong> 题</span><span>还剩 ${Math.max(0,count-mastered)} 题</span></div><div class="original-progress"><i style="width:${count?mastered/count*100:0}%"></i></div></div>`:''}</div><div class="${c('browse','heroCta')}">${link(last?'继续学习':'练习这一节',practiceURL(cat,activeBank),'ds-button replica-button primary')}${!last?button('选择其他章节','open-category','','quiet'):''}</div></div></section><div class="${c('browse','dashboardGrid')}"><section class="${c('browse','metricStrip')}" aria-label="考研目标与学习表现">${metric('考研倒计时',days,'天','clock',`考研初试 · ${escape(boot.settings.exam_date)}`)}${metric('今日刷题数',s.today_attempts||0,'题','chart')}${metric('连续学习',s.streak||0,'天','target')}</section>${heatmap()}<section class="${c('browse','panel')} original-surface"><header class="${c('browse','panelHeader')}"><h2>最近练习</h2></header>${recent.items.length?recent.items.map(r=>link(`<strong>#${r.question_id} ${escape(r.source||'')}</strong><span>${escape(localDate(r.created_at))}</span>`,practiceURL('', 'all')+`&q=%23${r.question_id}`,'original-recent-row')).join(''):'<p class="original-muted">还没有练习记录，标记掌握程度后会显示在这里。</p>'}</section></div></div>`);
}
function answerText(q){const d=q.document||q;return q.correct_answer||d.answer?.reference_answer_md||(d.answer?.option_ids||[]).map(id=>(d.options||[]).find(o=>o.id===id)?.label||id).join('、')||'暂无参考答案';}
function questionCard(q,index=0){const s=state(q),d=q.document||q,u=qUI(q),opts=d.options||[],focus=localStorage.getItem('daguan-layout')==='focus';return `<div class="${c('card','practiceCardLayout')}" data-question-card-layout="${focus?'focus':'classic'}" data-question-id="${q.id}"><article class="${c('card','card')}" id="question-${q.id}"><header class="${c('card','header')}"><div class="${c('card','metadata')}"><strong class="${c('card','number')}" title="题号 #${q.id}">${q.index||index+1}</strong><span class="original-source">${escape(q.source||'来源未注明')}</span><span class="${c('card','categoryPaths')}">${escape(q.category_full_path||q.category_name||'')}</span></div><div class="${c('card','headerActions')}"><details class="question-menu"><summary class="replica-button">更多操作</summary><div>${button(`${icon('star')} ${s.favorite?'取消收藏':'收藏'}`,'favorite',`data-id="${q.id}" aria-pressed="${s.favorite}"`,'quiet')}${button(`${icon('note')} 笔记`,'toggle-note',`data-id="${q.id}"`,'quiet')}${button('查看题号','question-id',`data-id="${q.id}"`,'quiet')}</div></details></div></header><div class="${c('card','document')}"><div data-question-document><div class="question-stem markdown">${md(d.stem_md||q.stem)}</div>${opts.length?`<ul class="question-options">${opts.map(o=>`<li role="button" tabindex="0" data-action="choice" data-id="${q.id}" data-option="${escape(o.id)}" data-choice-interactive="true" aria-pressed="${u.selected.includes(o.id)}" ${u.judged?`aria-disabled="true" data-choice-result="${(d.answer?.option_ids||[]).includes(o.id)?'correct':u.selected.includes(o.id)?'incorrect':''}"`:''}><span class="question-option-label">${escape(o.label)}.</span><span class="question-option-content markdown">${md(o.content_md)}</span></li>`).join('')}</ul>`:''}</div></div><div class="${c('card','actionToolbar')} ${c('card','practiceActionToolbar')}"><div class="${c('card','readingActions')}" aria-label="答案与解析">${button(`${icon('info')} ${u.answer?'收起答案':'查看答案'}`,'toggle-answer',`data-id="${q.id}" aria-pressed="${u.answer}"`,'quiet')}${button(`${icon('book')} ${u.explanation?'收起解析':'查看解析'}`,'toggle-explanation',`data-id="${q.id}" aria-pressed="${u.explanation}"`,'quiet')}</div><div class="${c('card','stateActions')}"><div class="${c('practice','practiceMasteryActions')}" aria-label="掌握状态">${[['learning','不熟练','repeat'],['not_known','不会','close'],['mastered','掌握','check']].map(([v,t,i])=>button(`${icon(i)} ${t}`,'mark',`data-id="${q.id}" data-mastery="${v}" aria-label="标记为${t}" aria-pressed="${s.mastery===v}" data-status="${v}"`)).join('')}</div></div>${u.answer||u.explanation?`<div class="${c('card','disclosure')}" data-question-document>${u.answer?`<section class="question-answer"><h3>答案</h3><div class="markdown">${md(answerText(q))}</div></section>`:''}${u.explanation?`<section class="question-explanation"><h3>解析</h3><div class="markdown">${md(d.explanation_md||q.answer_explanation||'暂无解析')}</div></section>`:''}</div>`:''}${u.note?`<section class="original-inline-note"><label for="note-${q.id}">题目笔记</label><textarea id="note-${q.id}" data-note-id="${q.id}" placeholder="记录思路、推导或易错点">${escape(u.draft??s.note)}</textarea><div><small id="note-status-${q.id}">${u.draft===undefined?'已保存':'尚未保存'}</small>${button('保存笔记','save-note',`data-id="${q.id}"`,'primary')}</div></section>`:''}</div></article></div>`;}
function replaceCard(q){const el=document.querySelector(`[data-question-id="${q.id}"]`);if(el)el.outerHTML=questionCard(q,results.indexOf(q));}
function pagination(data){if(data.total_pages<=1)return '';return `<div class="original-pagination">${button('上一页','page',`data-page="${data.page-1}" ${data.page<=1?'disabled':''}`)}<span>第 ${data.page} / ${Math.max(1,data.total_pages)} 页 · 共 ${data.total} 题</span>${button('下一页','page',`data-page="${data.page+1}" ${data.page>=data.total_pages?'disabled':''}`)}</div>`;}
