 if(route==='favorites')actions=`<select id="favorites-sort" aria-label="收藏时间排序">${options([['new','收藏时间：全部时间 · 新到旧'],['old','收藏时间：全部时间 · 旧到新']],p.get('sort')||'new')}</select>`;
 if(route==='notes')context='';
 if(route==='notes')content=`<form id="notes-filter" class="${c('notes','filters')}"><label>搜索题目笔记<input name="q" value="${escape(p.get('q')||'')}" placeholder="搜索思路、推导或关键词"></label><label>标签<select aria-label="按标签筛选"><option>全部标签</option></select></label><button class="replica-button" type="submit">搜索</button></form>`;
