 $('#app').innerHTML=frame(pageHeader(title,context,route==='notes'?'':`${route==='retest'?'待复测 ':''}${data.total} 题`,actions)+`<div class="original-page-body ${route==='questions'?'practice-list':''}">${p.get('q')&&route==='questions'?`<div class="original-search-result">搜索：${escape(p.get('q'))}${button('清除','clear-search','','quiet')}</div>`:''}${content}${listContent}${results.length&&localStorage.getItem('daguan-layout')==='focus'?`<div class="original-focus-navigation">${button('上一题','focus-prev',focusIndex===0?'disabled':'')}<span>${focusIndex+1} / ${results.length} 题</span>${button('下一题','focus-next',focusIndex===results.length-1?'disabled':'')}</div>`:''}</div>`,route==='questions'?c('practice','practicePage'):'');
