const kindNames={concept:'概念',property:'性质',condition:'判别条件',criterion:'判别条件',method:'方法',application:'应用',formula:'公式',theorem:'定理'};
async function loadKnowledgeContents(){
  if(knowledgeContents)return knowledgeContents;
  const response=await fetch('/app/data/knowledge-content.json');
  if(response.status===404)return knowledgeContents={};
  if(!response.ok)throw Error('知识点正文加载失败');
  const data=await response.json();
  if(data.schema_version!==1||!data.contents||typeof data.contents!=='object'||Array.isArray(data.contents))throw Error('知识点正文格式无效');
  return knowledgeContents=data.contents;
}
function knowledgeExplanation(point,failed){
  if(failed)return `<p class="${c('knowledge','phaseNote')}">原站讲解正文加载失败，请重新打开此知识点重试。</p>`;
  const content=knowledgeContents?.[point.conceptCode];
  if(!content||content.code!==point.conceptCode||typeof content.content_markdown!=='string'||!content.content_markdown.trim())return `<p class="${c('knowledge','phaseNote')}">此知识点的原站讲解正文尚未保存。</p>`;
  const heading=`# ${content.name}`,source=content.content_markdown;
  const body=source===heading?'':source.startsWith(heading+'\r\n')||source.startsWith(heading+'\n')?source.slice(heading.length).trimStart():source;
  return `<section class="${c('knowledge','explanation')}" aria-label="${escape(point.name)}讲解"><div class="Markdown-module__y7WeUW__markdown ${c('knowledge','explanationMarkdown')}">${md(body,{paragraphs:true})}</div></section>`;
}
async function renderKnowledge(epoch){if(!knowledgeData)knowledgeData=await fetch('/app/data/knowledge.json').then(r=>r.json());if(epoch!==renderEpoch)return;const p=params(),catalog=knowledgeData.catalog,subject=catalog.find(s=>s.treeCode===p.get('subject'))||catalog.find(s=>s.chapters.some(ch=>ch.reviewId===p.get('chapter')))||catalog[0],chapter=subject.chapters.find(ch=>ch.reviewId===p.get('chapter'))||subject.chapters[0],exam=Number(p.get('exam')||0),query=(p.get('q')||'').trim().toLowerCase(),point=chapter.items.find(i=>i.reviewId===p.get('point')),groups=query?subject.chapters.map(ch=>({...ch,items:ch.items.filter(i=>i.name.toLowerCase().includes(query))})).filter(ch=>ch.items.length):[chapter];let explanationFailed=false;if(point){try{await loadKnowledgeContents();}catch{explanationFailed=true;}if(epoch!==renderEpoch)return;}const url=changes=>'/math/knowledge?'+new URLSearchParams({subject:subject.treeCode,chapter:chapter.reviewId,...changes});$('#app').innerHTML=frame(pageHeader('知识图谱')+`<div class="${c('knowledge','content')}"><section class="${c('knowledge','overview')}"><h2>考研数学知识点</h2><p>按章节查找知识点，查看讲解与相关题目。</p></section><div class="${c('knowledge','toolbar')}"><div class="${c('knowledge','subjects')}" role="radiogroup" aria-label="选择知识学科">${catalog.map(s=>link(escape(s.label),'/math/knowledge?subject='+s.treeCode,'replica-button '+(s===subject?'active':''))).join('')}</div><form class="${c('knowledge','tools')}" id="knowledge-search"><input class="${c('knowledge','search')}" name="q" value="${escape(query)}" aria-label="搜索知识点" placeholder="搜索知识点或章节"><select name="exam" aria-label="选择考种范围">${options([['0','全部考种'],['1','数一'],['2','数二'],['3','数三']],exam)}</select></form></div><div class="${c('knowledge','workspace')}"><aside class="${c('knowledge','sidebar')}" aria-label="章节目录"><header class="${c('knowledge','directoryHeading')}"><h3>${escape(subject.label)}</h3><span>${subject.chapters.length} 个章节</span></header><nav class="${c('knowledge','chapterTree')}">${subject.chapters.map(ch=>link(`<span class="${c('knowledge','chapterName')}">${escape(ch.name)}</span><span>${ch.items.length}</span>`,url({chapter:ch.reviewId}),ch===chapter?'is-active':'')).join('')}</nav></aside><div class="${c('knowledge','main')}">${point?`<section class="original-knowledge-point"><h2>${escape(point.name)}</h2><p class="original-muted">${kindNames[point.kind]||point.kind} · ${point.exams.map(e=>'数'+['','一','二','三'][e]).join(' / ')}</p>${knowledgeExplanation(point,explanationFailed)}${link('返回知识点列表',url({}))}${button('查看相关题目','knowledge-related',`data-name="${escape(point.name)}"`)}</section>`:`<div class="${c('knowledge','pointGroups')}">${groups.map(ch=>{const items=ch.items.filter(i=>!exam||i.exams.includes(exam));return `<section class="${c('knowledge','pointGroup')}"><header class="${c('knowledge','listHeading')}"><h2>${escape(ch.name)}</h2><span>${items.length} 个知识点</span></header><ul class="${c('knowledge','pointGrid')}">${items.map(i=>`<li>${link(`<span class="${c('knowledge','pointContent')}"><span class="${c('knowledge','pointName')}">${escape(i.name)}</span><span class="${c('knowledge','pointSummary')}">${kindNames[i.kind]||escape(i.kind)}</span></span>${icon('chevron')}`,url({chapter:ch.reviewId,point:i.reviewId}),c('knowledge','pointTag'))}</li>`).join('')}</ul></section>`;}).join('')}</div>`}</div></div></div>`,c('knowledge','page'));}
async function renderRecords(epoch){const p=params(),type=p.get('record_type')||'all',data=await api('/records?'+new URLSearchParams({page:p.get('page')||'1',per_page:'30',record_type:type,start:p.get('start')||'',end:p.get('end')||'',sort:p.get('sort')||'new'}));if(epoch!==renderEpoch)return;pageInfo=data;const start=p.get('start')||'',end=p.get('end')||'',sort=p.get('sort')||'new';const items=data.items;const names={correct:'作答正确',wrong:'作答错误',favorite:'收藏',unfavorite:'取消收藏',not_started:'取消标记',mastered:'掌握',learning:'不熟练',not_known:'完全不会'};$('#app').innerHTML=frame(pageHeader('学习记录',`<span class="original-muted">${sort==='new'?'最新优先':'最早优先'}</span>`,`共 ${data.total} 条`)+`<div class="original-page-body ${c('records','page')}"><section class="original-record-filter"><span>类型</span>${[['all','全部'],['favorite','收藏'],['learning','不熟练'],['not_known','完全不会'],['mastered','掌握']].map(([v,t])=>button(t,'record-filter',`data-filter="${v}" aria-pressed="${type===v}"`)).join('')}<select id="record-sort" aria-label="学习记录时间排序">${options([['new','最新优先'],['old','最早优先']],sort)}</select></section><form id="record-dates" class="original-record-dates"><label>开始日期<input type="date" name="start" value="${start}"></label><label>结束日期<input type="date" name="end" value="${end}"></label></form><p class="original-muted original-record-caption">记录收藏、掌握状态变化和练习；同一道题的多次操作分别计数。日期按北京时间显示。</p><section class="original-record-surface">${items.length?items.map(r=>`<div class="original-record-row">${link(`#${r.question_id} ${escape(r.source||'')}`,practiceURL('','all')+`&q=%23${r.question_id}`)}<span>${names[r.action||r.result]||escape(r.action||r.result)}</span><time>${escape(localDate(r.created_at))}</time></div>`).join('')+pagination(data):empty('暂无内容','当前条件下没有学习记录。收藏题目或更新掌握状态后，会在这里留下记录。')}</section></div>`,c('records','page'));}
function renderPaper(){const ruleLabels=['高数 · 选择题 4 题','线代 · 选择题 3 题','概率 · 选择题 3 题','高数 · 填空题 4 题','线代 · 填空题 1 题','概率 · 填空题 1 题','高数 · 大题 4 题','线代 · 大题 1 题','概率 · 大题 1 题'];$('#app').innerHTML=frame(pageHeader('智能组卷',`<div class="original-segment">${['standard','custom'].map(mode=>button(mode==='standard'?'标准卷':'自定义卷','paper-mode',`data-mode="${mode}" aria-pressed="${paperMode===mode}"`)).join('')}</div>`,'',paperItems.length?button('打印题目','print'):'')+`<div class="original-page-body ${c('paper','page')}">${paperItems.length?`<div class="original-paper-created">${button('返回组卷配置','paper-reset')}<span>本次组卷 ${paperItems.length} 题</span></div><div class="practice-list">${paperItems.map(questionCard).join('')}</div>`:`<div class="${c('paper','configurationGrid')}"><section class="${c('paper','rules')} original-surface"><h2>${paperMode==='standard'?'标准卷规则':'自定义卷范围'}</h2>${paperMode==='standard'?`<ul class="original-standard-rules">${ruleLabels.map(t=>`<li>${t}</li>`).join('')}</ul><p class="original-muted">题目不足或缺少学科、专题信息时，按现有题目组卷，并列出未满足的要求。</p><p class="original-muted">所选题目不足时，从题库补入，优先待巩固题；仍不足时，按实际题量组卷。</p>`:`<form id="paper-config" class="original-paper-config"><label>题库<select name="list">${options(Object.entries(bankNames).filter(([v])=>v!=='all'),paperConfig.list||'complete')}</select></label><label>分类<select name="category"><option value="">全部分类</option>${(boot.directories.complete||[]).map(n=>`<option value="${nodeId(n)}" ${String(paperConfig.category)===String(nodeId(n))?'selected':''}>${escape(nodeLabel(n))}</option>`).join('')}</select></label><label>题型<select name="type">${options([['','全部题型'],['single_choice','选择题'],['fill','填空题'],['subjective','大题']],paperConfig.type||'')}</select></label><label>题目数量<input type="number" name="count" value="${paperConfig.count||22}" min="1" max="100"></label></form>`}</section><div class="${c('paper','rightRail')}"><section class="${c('paper','preview')} original-surface"><h2>组卷检查</h2><p class="${c('paper','previewStatus')}">${paperCheck?'检查完成。':'配置已变更，请重新检查。'}</p><div class="${c('paper','previewMeta')}"><span>预计 ${paperCheck?.expected_total??'—'} 题</span><span>候选 ${paperCheck?Array.isArray(paperCheck.candidates)?paperCheck.candidates.length:paperCheck.candidates:'—'} 题</span></div>${paperCheck?.shortages?.length?`<p class="original-muted">${paperCheck.shortages.map(s=>escape(JSON.stringify(s))).join('；')}</p>`:''}${button('检查题量','paper-check')}${button('创建智能组卷','paper-create',paperCheck?.expected_total?'':'disabled','primary')}</section><section class="${c('paper','settings')} original-surface"><h2>题目来源</h2><label class="original-checkbox"><input type="checkbox" id="paper-wrong" ${paperConfig.prioritize_wrong!==false?'checked':''}>错题</label><label class="original-checkbox"><input type="checkbox" id="paper-favorites" ${paperConfig.prioritize_favorites!==false?'checked':''}>收藏题</label></section></div></div>`}</div>`,c('paper','page'));results=paperItems;}
function renderSettings(){const s=boot.settings,layout=localStorage.getItem('daguan-layout')||'classic';$('#app').innerHTML=frame(pageHeader('通用设置')+`<div class="${c('settings','settingsWorkspace')}"><div class="${c('settings','surface')}"><section class="${c('settings','preferencesSection')}" aria-label="学习与显示"><div class="${c('settings','preferencesHeading')}"><h2>学习与显示</h2><span>仅在当前浏览器生效</span></div><div class="original-setting-row"><label>学习布局</label><div class="original-layout-options">${[['classic','经典布局','连续浏览多题'],['focus','专注布局','逐题作答']].map(([v,t,d])=>`<label><span><strong>${t}</strong><small>${d}</small></span><input type="radio" name="layout" value="${v}" ${layout===v?'checked':''}></label>`).join('')}</div></div><div class="original-setting-row"><label>页面外观</label><div class="original-segment">${button('浅色','set-theme','data-theme="light" aria-pressed="'+(s.theme==='light')+'"')}${button('深色','set-theme','data-theme="dark" aria-pressed="'+(s.theme==='dark')+'"')}</div></div></section><section class="${c('settings','settingsSection')}"><h2 class="original-settings-heading">备考科目</h2><form id="settings-form"><div class="original-setting-row"><label>备考科目</label><div class="original-subject-options">${[['all','全部'],['math_1','数一'],['math_2','数二'],['math_3','数三']].map(([v,t])=>`<label><input type="radio" name="exam_subject" value="${v}" ${(s.exam_subject||'all')===v?'checked':''}>${t}</label>`).join('')}</div></div><div class="original-setting-row"><label for="exam-date">考研日期</label><input type="date" id="exam-date" name="exam_date" value="${escape(s.exam_date)}" required></div><div class="original-save-row"><button class="replica-button primary" type="submit">保存科目</button></div></form></section><details class="${c('settings','settingsSection')}"><summary class="original-setting-summary"><strong>学习记录与题单</strong><span>导入与导出 ${icon('chevron')}</span></summary><div class="original-sync-body">${link('学习记录',paths.records,'replica-button')}${button('导出学习数据','export')}<label class="replica-button">导入学习数据<input type="file" id="import-file" accept=".json,application/json" hidden></label><p id="import-result" class="original-muted" role="status"></p></div></details></div></div>`,c('settings','settingsPage'));}
function categoryTree(nodes,depth=0){return (nodes||[]).map(n=>n.children?.length?`<details ${depth<1?'open':''}><summary>${md(nodeLabel(n))}<small>${total(n)} 题</small></summary><div>${button('练习本分类','pick-category',`data-category="${nodeId(n)}"`,'quiet')}${categoryTree(n.children,depth+1)}</div></details>`:button(`${md(nodeLabel(n))}<small>${total(n)} 题</small>`,'pick-category',`data-category="${nodeId(n)}"`,'quiet')).join('');}
function openCategory(){const list=params().get('list')||activeBank;$('#category-dialog').innerHTML=`<header><h2>选择题目分类</h2>${button(icon('close'),'close-category','aria-label="关闭分类"','quiet')}</header><div class="original-category-tree">${route==='home'?`<div class="original-segment">${[['complete','完整'],['core','严选'],['exam','真题'],['mock','模拟题']].map(([v,t])=>button(t,'category-bank',`data-list="${v}"`)).join('')}</div>`:''}${button('全部分类','pick-category','data-category=""')}${categoryTree(boot.directories[list])}</div>`;$('#category-dialog').showModal();}
function openSearch(){const p=params();$('#search-dialog').innerHTML=`<header><h2>搜索题库</h2>${button(icon('close'),'close-search','aria-label="关闭搜索"','quiet')}</header><form id="search-form"><input name="q" value="${escape(p.get('q')||'')}" placeholder="题号、题干、来源或年份" aria-label="搜索题目" autofocus required><button type="submit" class="replica-button primary">搜索</button></form>`;$('#search-dialog').showModal();}
async function saveDrafts(){for(const q of results){const u=ui.get(q.id);if(u?.draft!==undefined){const data=await api(`/questions/${q.id}/state`,'PUT',{note:u.draft});q.state=data.state||data;u.draft=undefined;}}}
async function render(){const epoch=++renderEpoch;const requestedBank=params().get('list');if(['complete','core','exam','mock'].includes(requestedBank)){activeBank=requestedBank;localStorage.setItem('daguan-bank',activeBank);}route=Object.keys(paths).find(k=>paths[k]===location.pathname)||(location.pathname==='/math/questions'?'questions':location.pathname.startsWith('/math/questions/')?'questions':'home');document.title='学习区 · 大观园';document.body.dataset.route=route;try{if(route==='home')await renderHome(epoch);else if(['questions','favorites','notes','retest'].includes(route))await renderQuestions(epoch);else if(route==='mastery')await renderMastery(epoch);else if(route==='knowledge')await renderKnowledge(epoch);else if(route==='records')await renderRecords(epoch);else if(route==='paper')renderPaper();else if(route==='settings')renderSettings();}catch(error){if(epoch===renderEpoch)$('#app').innerHTML=frame(pageHeader(titles[route]||'学习区')+empty('无法加载',escape(error.message))+button('重新加载','retry'));}finally{if(epoch===renderEpoch){const main=$('#main');if(main)main.scrollTop=0;const viewport=document.querySelector('[data-learning-immersive-scroll-owner]');if(viewport)viewport.scrollTop=0;}}}
function paperPayload(){if($('#paper-config'))paperConfig={...paperConfig,...Object.fromEntries(new FormData($('#paper-config')))};paperConfig.prioritize_wrong=$('#paper-wrong')?.checked??paperConfig.prioritize_wrong??true;paperConfig.prioritize_favorites=$('#paper-favorites')?.checked??paperConfig.prioritize_favorites??true;return {...paperConfig,mode:paperMode,count:Number(paperConfig.count||22),subject:boot.settings.exam_subject||'all'};}
async function act(action,el){const id=Number(el.dataset.id),q=results.find(q=>q.id===id),u=q&&qUI(q);
 if(action==='retry')return render();
 if(action==='mobile-more'){const dialog=$('#more-dialog');dialog.innerHTML=`<header><h2>更多</h2>${button(icon('close'),'close-more','aria-label="关闭更多菜单"','quiet')}</header><nav class="learning-shell__mobile-more-menu-list">${[['knowledge','map'],['paper','paper'],['notes','note']].map(([k,i])=>link(`${icon(i)} ${titles[k]}`,paths[k],'learning-shell__mobile-more-link')).join('')}</nav>`;return dialog.showModal();}if(action==='close-more')return $('#more-dialog').close();
 if(action==='open-category')return openCategory();if(action==='close-category')return $('#category-dialog').close();
 if(action==='category-bank'){activeBank=el.dataset.list;localStorage.setItem('daguan-bank',activeBank);$('#category-dialog').close();return openCategory();}
 if(action==='pick-category'){await saveDrafts();$('#category-dialog').close();if(route==='home')return navigate(practiceURL(el.dataset.category));return updateQuery({category:el.dataset.category,page:1});}
 if(action==='open-search')return openSearch();if(action==='close-search')return $('#search-dialog').close();
 if(action==='clear-search')return updateQuery({q:null,page:1});
 if(action==='switch-bank'){activeBank=el.dataset.list;localStorage.setItem('daguan-bank',activeBank);return render();}
 if(action==='collapse-sidebar'){sidebarCollapsed=!sidebarCollapsed;return render();}
 if(action==='open-sidebar')return $('#sidebar').classList.add('open');if(action==='close-sidebar')return $('#sidebar')?.classList.remove('open');
 if(action==='settings')return navigate('/settings');
 if(action==='theme'||action==='set-theme'){const theme=el.dataset.theme||(document.documentElement.dataset.theme==='dark'?'light':'dark');await api('/settings','PUT',{theme});boot.settings.theme=theme;setTheme(theme);return render();}
 if(action==='page'){await saveDrafts();return updateQuery({page:el.dataset.page});}
 if(action==='toggle-answer'||action==='toggle-explanation'){const key=action==='toggle-answer'?'answer':'explanation';u[key]=!u[key];if(u.answer&&u.selected.length&&!u.judged){const correct=q.document?.answer?.option_ids||[];if(correct.length){const right=correct.length===u.selected.length&&correct.every(i=>u.selected.includes(i));const result=await api(`/questions/${id}/attempt`,'POST',{result:right?'correct':'wrong',answer:u.selected.join(','),duration_seconds:Math.round((Date.now()-u.start)/1000)});q.state=result.state;u.judged=true;}}return replaceCard(q);}
 if(action==='choice'){if(u.judged)return;if(q.question_type==='multiple_choice'){u.selected=u.selected.includes(el.dataset.option)?u.selected.filter(i=>i!==el.dataset.option):[...u.selected,el.dataset.option];}else u.selected=[el.dataset.option];return replaceCard(q);}
 if(action==='favorite'){const updated=await api(`/questions/${id}/state`,'PUT',{favorite:!state(q).favorite});q.state=updated.state||updated;replaceCard(q);return;}
 if(action==='mark'){const mastery=state(q).mastery===el.dataset.mastery?'not_started':el.dataset.mastery;const updated=await api(`/questions/${id}/state`,'PUT',{mastery});q.state=updated.state||updated;return replaceCard(q);}
 if(action==='toggle-note'){u.note=!u.note;return replaceCard(q);}
 if(action==='save-note'){const updated=await api(`/questions/${id}/state`,'PUT',{note:u.draft??state(q).note});q.state=updated.state||updated;u.draft=undefined;replaceCard(q);return toast('笔记已保存');}
 if(action==='question-id')return toast(`题号 #${id}`);
 if(action==='focus-prev'||action==='focus-next'){await saveDrafts();focusIndex+=action==='focus-next'?1:-1;return render();}
 if(action==='map-category')return updateQuery({category:el.dataset.category});if(action==='map-filter')return updateQuery({filter:params().get('filter')===el.dataset.filter?'all':el.dataset.filter});
 if(action==='map-practice')return navigate(practiceURL(params().get('category')||'', 'complete')+(params().get('filter')?`&filter=${params().get('filter')}`:''));
 if(action==='activity-date')return navigate('/math/records?start='+el.dataset.date+'&end='+el.dataset.date);
 if(action==='record-filter')return updateQuery({record_type:el.dataset.filter,page:1});
 if(action==='knowledge-related'){return navigate(practiceURL('','all')+'&q='+encodeURIComponent(el.dataset.name));}
 if(action==='paper-mode'){paperMode=el.dataset.mode;paperCheck=null;return renderPaper();}
 if(action==='paper-check'){paperCheck=await api('/paper/check','POST',paperPayload());return renderPaper();}
 if(action==='paper-create'){const data=await api('/paper','POST',paperPayload());paperItems=data.items;return renderPaper();}
 if(action==='paper-reset'){await saveDrafts();paperItems=[];return renderPaper();}
 if(action==='print')return window.print();
 if(action==='retest-help')return toast('标记“不熟练”或“不会”加入错题；本地版次日到期，标记“掌握”后移出。');
 if(action==='export'){const data=await api('/export'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`大观园-学习备份-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
}
document.addEventListener('click',async e=>{const a=e.target.closest('a[data-route]');if(a&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey){e.preventDefault();try{await saveDrafts();$('#more-dialog').close();navigate(a.getAttribute('href'));}catch(err){toast(err.message);}return;}const el=e.target.closest('[data-action]');if(el&&!el.disabled){e.preventDefault();try{await act(el.dataset.action,el);}catch(err){toast(err.message);}}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['search-form','notes-filter','settings-form','knowledge-search','record-dates'].includes(f.id))return;e.preventDefault();try{const values=Object.fromEntries(new FormData(f));if(f.id==='search-form'){$('#search-dialog').close();return navigate(practiceURL('',route==='home'||route==='questions'?(params().get('list')||activeBank):'all')+'&q='+encodeURIComponent(values.q));}if(f.id==='notes-filter')return updateQuery({q:values.q,page:1});if(f.id==='knowledge-search')return updateQuery({...values,point:null});if(f.id==='record-dates')return updateQuery(values);if(f.id==='settings-form'){await api('/settings','PUT',values);boot=await api('/bootstrap');return toast('设置已保存');}}catch(err){toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.dataset.noteId){const id=Number(e.target.dataset.noteId),q=results.find(q=>q.id===id);qUI(q).draft=e.target.value;const status=$(`#note-status-${id}`);if(status)status.textContent='尚未保存';}});
document.addEventListener('change',async e=>{const t=e.target;try{if(t.name==='layout'){localStorage.setItem('daguan-layout',t.value);return renderSettings();}if(t.id==='enhance-map'){localStorage.setItem('daguan-enhance-map',String(t.checked));return render();}if(t.id==='retest-filter')return updateQuery({filter:t.value,page:1});if(t.id==='record-sort')return updateQuery({sort:t.value,page:1});if(t.closest('#record-dates'))return updateQuery({...Object.fromEntries(new FormData($('#record-dates'))),page:1});if(t.closest('#knowledge-search'))return updateQuery({...Object.fromEntries(new FormData($('#knowledge-search'))),point:null});if(t.closest('#paper-config')||t.id==='paper-wrong'||t.id==='paper-favorites'){paperPayload();paperCheck=null;return renderPaper();}if(t.id==='favorites-sort')return updateQuery({sort:t.value,page:1});if(t.id==='import-file'){const file=t.files[0];if(!file)return;if(file.size>16*1024*1024)throw Error('备份文件超过16 MB');const result=await api('/import','POST',JSON.parse(await file.text()));boot=await api('/bootstrap');setTheme(boot.settings.theme);$('#import-result').textContent=`导入完成，原数据库已自动备份。${result.states_skipped_older?`保留${result.states_skipped_older}条较新的状态。`:''}`;}}catch(err){toast(err.message);}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();openSearch();}if(['Enter',' '].includes(e.key)&&e.target.matches('[data-action="choice"]')){e.preventDefault();act('choice',e.target).catch(err=>toast(err.message));}});
window.addEventListener('popstate',render);
async function init(){try{boot=await api('/bootstrap');setTheme(boot.settings.theme||'light');try{assets=(await fetch('/raw/asset-recovery.json').then(r=>r.json())).assets||{};}catch{}await render();}catch(err){$('#app').innerHTML=empty('无法连接本地服务',escape(err.message));}}
init();
